//! Helpers shared by the integration test binaries.
use std::fs;
use std::path::PathBuf;
use std::process;

const CHUNK_SIZE: usize = 65536;

/// A generated file in the system temp directory, removed again on drop.
pub struct TempFile {
    path: PathBuf,
    contents: Vec<u8>,
}

impl TempFile {
    /// Writes `size` pseudo-random bytes (so that no two 64KB chunks are alike) to a file whose
    /// name is unique to this process and `tag`.
    pub fn generate(tag: &str, size: usize) -> Self {
        let mut state: u64 = 0x9e37_79b9_7f4a_7c15;
        let contents: Vec<u8> = (0..size)
            .map(|_| {
                state = state
                    .wrapping_mul(6_364_136_223_846_793_005)
                    .wrapping_add(1_442_695_040_888_963_407);
                (state >> 56) as u8
            })
            .collect();
        let path = std::env::temp_dir().join(format!("oshash-test-{}-{tag}", process::id()));
        fs::write(&path, &contents).unwrap();

        Self { path, contents }
    }

    /// The file's path in the form the `oshash` API accepts.
    pub fn path(&self) -> &str {
        self.path.to_str().unwrap()
    }

    /// The hash computed straight from the generated bytes, independently of the library: the
    /// file size plus every little-endian `u64` of the first and last 64KB, wrapping.
    pub fn expected_hash(&self) -> String {
        let (first, rest) = self.contents.split_at(CHUNK_SIZE);
        let last = &rest[rest.len() - CHUNK_SIZE..];
        let hash = first
            .chunks_exact(8)
            .chain(last.chunks_exact(8))
            .map(|word| u64::from_le_bytes(word.try_into().unwrap()))
            .fold(self.contents.len() as u64, u64::wrapping_add);

        format!("{hash:016x}")
    }
}

impl Drop for TempFile {
    fn drop(&mut self) {
        // Best effort: a leftover file in the temp directory is harmless.
        let _ = fs::remove_file(&self.path);
    }
}

/// File sizes exercising the chunk layout: exactly two adjacent chunks, two chunks separated by a
/// single byte, and a size that is a multiple of neither 64KB nor 8.
pub const GENERATED_SIZES: [(&str, usize); 3] = [
    ("exactly-128k", 2 * CHUNK_SIZE),
    ("128k-plus-one", 2 * CHUNK_SIZE + 1),
    ("unaligned", 3 * CHUNK_SIZE + 12_345),
];
